def parse_price(s: str) -> float | None:
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None

    normalized = ''.join(ch for ch in text.lower() if ch.isalnum())
    if normalized == 'gratis':
        return 0.0
    if normalized == 'bieden':
        return None

    cleaned = text.replace('€', '').replace('−', '-')
    cleaned = ''.join(cleaned.split())
    for token in ('EUR', 'eur', 'Euro', 'euro'):
        cleaned = cleaned.replace(token, '')
    cleaned = ''.join(cleaned.split())
    if not cleaned:
        return None

    # Dutch format: '.' thousands separator, ',' decimal separator,
    # ',-' means zero decimal places
    cleaned = cleaned.replace('.', '')
    if cleaned.endswith(',-'):
        cleaned = cleaned[:-2]
    cleaned = cleaned.replace(',', '.')

    try:
        return float(cleaned)
    except ValueError:
        return None

import re

_POSTCODE_RE = re.compile(r'^([1-9][0-9]{3})(?: )?([A-Za-z]{2})$')

def is_valid_postcode(s: str) -> bool:
    if not isinstance(s, str):
        return False
    match = _POSTCODE_RE.match(s)
    if match is None:
        return False
    return match.group(2).upper() not in {'SA', 'SD', 'SS'}

import datetime


def next_pickup_slot(now: datetime.datetime) -> datetime.datetime:
    day = now.date()
    for _ in range(8):
        weekday = day.weekday()  # Monday=0 ... Sunday=6
        if weekday < 5:
            start_time, end_time = datetime.time(18, 0), datetime.time(21, 0)
        elif weekday == 5:
            start_time, end_time = datetime.time(10, 0), datetime.time(16, 0)
        else:
            day += datetime.timedelta(days=1)
            continue

        window_start = datetime.datetime.combine(day, start_time, tzinfo=now.tzinfo)
        window_end = datetime.datetime.combine(day, end_time, tzinfo=now.tzinfo)

        slot = window_start
        while slot < window_end:
            if slot >= now:
                return slot.replace(second=0, microsecond=0)
            slot += datetime.timedelta(minutes=30)

        day += datetime.timedelta(days=1)

    raise RuntimeError("No pickup slot found")

def dedupe(listings: list[dict]) -> list[dict]:
    def norm_title(title):
        return ' '.join(str(title).split()).lower()

    best = {}  # key -> (date, index, item)
    for i, item in enumerate(listings):
        key = (norm_title(item['title']), item['price'])
        d = item['date']
        if key not in best:
            best[key] = (d, i, item)
        else:
            bd, _, _ = best[key]
            if d < bd:
                best[key] = (d, i, item)

    kept = sorted(best.values(), key=lambda x: x[1])
    return [item for _, _, item in kept]

def add_tag(tag, tags=None):
    if tags is None:
        tags = []
    new_tags = list(tags)
    if tag not in new_tags:
        new_tags.append(tag)
    return sorted(new_tags)

import csv
from io import StringIO

def totals_by_payment(csv_text: str) -> dict[str, int]:
    rows = list(csv.reader(StringIO(csv_text)))
    if not rows:
        return {}

    header = [cell.strip().lstrip("\ufeff").lower() for cell in rows[0]]
    try:
        price_idx = header.index("price")
        payment_idx = header.index("payment")
    except ValueError:
        return {}

    totals: dict[str, int] = {}
    for row in rows[1:]:
        if not row:
            continue
        if len(row) <= max(price_idx, payment_idx):
            continue

        raw_price = row[price_idx].strip().replace(",", "").replace("$", "").strip()
        payment = row[payment_idx].strip().lower()
        if not payment or not raw_price:
            continue

        try:
            price = int(raw_price)
        except ValueError:
            try:
                price = int(float(raw_price))
            except ValueError:
                continue

        totals[payment] = totals.get(payment, 0) + price

    return totals

import time

def retry(fn, attempts=3, exceptions=(Exception,), sleep=time.sleep, base_delay=1.0):
    for i in range(attempts):
        try:
            return fn()
        except exceptions:
            if i == attempts - 1:
                raise
            sleep(base_delay * (2 ** i))

import json


def extract_json(text):
    if not isinstance(text, str):
        return None
    decoder = json.JSONDecoder()
    pos = 0
    while True:
        start = text.find('{', pos)
        if start == -1:
            return None
        try:
            obj, _end = decoder.raw_decode(text[start:])
        except json.JSONDecodeError:
            pos = start + 1
            continue
        if isinstance(obj, dict):
            return obj
        pos = start + 1
